/* ------------------------------------------------------------------ public API (in-process) */

/** What other modules may call in-process: `ctx.use('workqueues')` (or `ctx.tryUse` for an optional dependency). */
export interface WorkqueuesPublicApi {
  /** Create or refresh a work item. Idempotent on dedupeKey: a second call updates title, deadline and amount instead of creating a duplicate. For checks that are not events (e.g. finance's daily reconciliation, returns' deadline job). input.sourceModule names the caller. Used by: finance, returns, support, sellers, trust, inventory, warehouse, customers, reviews, purchasing, messaging, payments. */
  raise(input: RaiseInput): Promise<WorkItem>;
  /** Close open items for a fixed source; returns how many closed Used by: finance, returns, support, sellers, trust, inventory, warehouse, reviews, purchasing, messaging, payments. */
  resolveBySource(dedupeKey: string, outcome: { note: string, by: common.Actor }): Promise<number>;
  /** Open items about one order, seller, case or payout, for detail pages Used by: orders, sellers, support, finance, graphql. */
  listForSubject(subjectType: string, subjectId: string): Promise<WorkItem[]>;
  /** Counts for other dashboards Used by: reports. */
  openCounts(queueKeys: string[]): Promise<Record<string, { open: number, overdue: number }>>;
  /** Open seller-visible tasks by kind for the seller dashboard Used by: reports. */
  sellerTaskCounts(sellerId: string): Promise<Record<string, number>>;
  /** The My work queues screen for the calling staff member (same as GET /api/admin/workqueues/me) Used by: graphql. */
  getMyQueues(principal: identity.Principal): Promise<MyQueues>;
  /** Needs-attention tiles, overdue dispatch items and team on shift for the admin dashboard (same as GET /summary), limited to the queues the caller may see Used by: graphql. */
  getWorkSummary(principal: identity.Principal): Promise<WorkSummary>;
  /** Work items in the queues the caller may see (same as GET /items) Used by: graphql. */
  listItems(filter: { queueKeys?: string[], areas?: string[], kinds?: string[], states?: string[], assignedToMe?: boolean, overdueOnly?: boolean, overdueOver?: string, sellerId?: string, sellerKind?: string, search?: string }, page: common.PageInput, principal: identity.Principal): Promise<common.Page<WorkItem>>;
  /** One work item with notes and history, if the caller may see its queue Used by: graphql. */
  getItem(itemId: string, principal: identity.Principal): Promise<WorkItem | null>;
  /** Export rows for reports dataset workqueues.admin.items (limited to the principal's queue areas) Used by: reports. */
  exportRows(dataset: string, filters: unknown, principal: identity.Principal, cursor?: string): Promise<{ rows: unknown[], nextCursor?: string }>;
}

/* ------------------------------------------------------------------ tables (Kysely row types) */

/** Tables in the `workqueues` schema. Use with `ctx.db` (already scoped to the schema). */
export interface WorkqueuesDb {
  queues: {
    key: string;
    name: string;
    area: string;
    owner_role: string;
    lead_staff_id: string;
    backup_staff_id: string;
    escalation_route: Json;
    escalation_label: string;
    default_deadline_minutes: number;
    business_hours_only: boolean;
    pause_while_waiting: boolean;
    screen: string;
    screen_filter: string | null;
    visible_to_seller: boolean;
    active: boolean;
    updated_by: string;
    updated_at: Date;
  };
  /** Event → queue mapping, seeded per module and editable only by migration or admin with reason */
  intake_rules: {
    id: string;
    event: string;
    queue_key: string;
    kind: string;
    title_template: string;
    dedupe_key_template: string;
    deadline_rule: string;
    priority: string;
    resolves_on: Json;
    active: boolean;
  };
  items: {
    id: string;
    ref: string;
    queue_key: string;
    kind: string;
    title: string;
    summary: string | null;
    subject_type: string;
    subject_id: string;
    subject_ref: string | null;
    subject_label: string | null;
    /** WorkSubject[] */
    related_subjects: Json;
    seller_id: string | null;
    seller_name: string | null;
    customer_id: string | null;
    amount_minor: number | null;
    currency: string | null;
    owner_role: string;
    assignee_staff_id: string | null;
    due_at: Date;
    deadline_state: 'on_time' | 'due_soon' | 'overdue';
    priority: string;
    state: string;
    waiting_on: string | null;
    /** set on wait, cleared on resume; used to push due_at when the queue pauses while waiting */
    waiting_since: Date | null;
    escalation_level: number;
    escalated_to: string | null;
    dedupe_key: string;
    source_module: string;
    source_event: string | null;
    links: Json;
    visible_to_seller: boolean;
    opened_at: Date;
    updated_at: Date;
    resolved_at: Date | null;
    resolution: Json | null;
    /** resolved items past itemRetentionDays; rows stay */
    archived_at: Date | null;
  };
  /** History: raised, refreshed, assigned, state changes, escalations, notes */
  item_events: {
    id: string;
    item_id: string;
    kind: string;
    detail: Json;
    actor_kind: string;
    actor_id: string | null;
    at: Date;
  };
  item_notes: {
    id: string;
    item_id: string;
    body: string;
    author_id: string;
    author_name: string;
    at: Date;
  };
  saved_filters: {
    id: string;
    owner_staff_id: string;
    name: string;
    shared: boolean;
    target: string;
    screen: string | null;
    screen_state: string | null;
    filters: Json;
    created_at: Date;
  };
  day_end_reviews: {
    id: string;
    date: string;
    due_at: Date;
    state: string;
    shared_with_roles: Json;
    items: Json;
    completed_by: string | null;
    completed_at: Date | null;
    summary_sent_to: Json;
  };
  routine_templates: {
    id: string;
    title: string;
    area_label: string;
    owner_roles: Json;
    due_time: string;
    weekdays: Json;
    active: boolean;
  };
  routine_checks: {
    id: string;
    template_id: string;
    date: string;
    owner_staff_id: string;
    due_at: Date;
    state: string;
    done_at: Date | null;
    done_by: string | null;
    note: string | null;
    check_ins: Json;
  };
  /** End-of-day snapshot per queue for 'more than yesterday' deltas and trend reports */
  daily_counts: {
    queue_key: string;
    date: string;
    open: number;
    overdue: number;
    opened: number;
    resolved: number;
    median_resolve_minutes: number | null;
  };
}

